import { afterAll, beforeAll, expect, it, vi } from "vitest";
vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
import * as projectRepo from "@/server/repositories/project-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as svc from "@/server/services/issue-service";
import { subscribe } from "@/lib/event-bus";
import { registerActivityListeners } from "@/server/services/activity-service";
import { registerSearchListeners } from "@/server/services/search-service";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as searchRepo from "@/server/repositories/search-repository";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); });
afterAll(() => cleanup());
it("moves", async () => {
  const offs = [registerActivityListeners(), registerSearchListeners()];
  const t = await createTenant("mv");
  const p2 = await projectRepo.insertProject({ orgId: t.org.id, name: "b", slug: "b", key: "B", description: null, visibility: "org", leadId: t.userIds.owner, color: "#000000", targetDate: null });
  const a = t.project.id;
  const ev: unknown[] = [];
  subscribe("issue.moved", (p) => { ev.push(p); });
  const i1 = await svc.createIssue(t.actors.member, issueInput(t.org.id, a, { title: "one issue" }));
  const i2 = await svc.createIssue(t.actors.member, issueInput(t.org.id, a, { title: "two issue" }));
  expect((await svc.moveIssueToProject(t.actors.member, { orgId: t.org.id, issueId: i1.id, toProjectId: a })).number).toBe(1);
  expect(ev.length).toBe(0);
  const m = await svc.moveIssueToProject(t.actors.member, { orgId: t.org.id, issueId: i2.id, toProjectId: p2.id });
  expect([m.projectId, m.number]).toEqual([p2.id, 1]);
  const i3 = await svc.createIssue(t.actors.member, issueInput(t.org.id, a, { title: "three issue" }));
  expect(i3.number).toBe(3);
  const back = await svc.moveIssueToProject(t.actors.member, { orgId: t.org.id, issueId: i2.id, toProjectId: a });
  expect(back.number).toBe(4);
  expect(ev.length).toBe(2);
  await new Promise((r) => setTimeout(r, 20));
  const act = await activityRepo.listActivity({ orgId: t.org.id, action: ["issue.moved"], limit: 10, cursor: null } as never);
  console.log(JSON.stringify(act.items.map((x) => [x.projectId, x.metadata])));
  const s = await searchRepo.searchDocuments({ orgId: t.org.id, q: "two", kinds: [], projectId: a, limit: 10, cursor: null } as never);
  expect(s.total).toBe(1);
  await expect(svc.moveIssueToProject(t.actors.viewer, { orgId: t.org.id, issueId: i1.id, toProjectId: p2.id })).rejects.toThrow();
  offs.forEach((o) => o());
});
EOF
